<h1><?= $this->h($ticket['title']) ?></h1><p><?= $this->status($ticket['state']) ?> · <?= $this->status($ticket['kind']) ?></p><p>شناسه پرونده: <code><?= $this->h($ticket['id']) ?></code></p><?php if($ticket['booking_id']): ?><p>رزرو مرتبط: <code><?= $this->h($ticket['booking_id']) ?></code></p><?php endif; ?>
